  /// Types whose payments say nothing about the place (core `PLACELESS_TYPES`).
  static let placeless: Set<String> = ["transport.parking", "transport.taxi", "transport.publicTransport", "transport.bike", "personal.cash", "home.rent", "home.utilities", "home.internet", "bills.subscriptions", "bills.insurance", "bills.taxes", "bills.fees", "bills.services", "personal.charity", "fun.travel", "savings.savings", "savings.investments", "income.salary", "income.freelance", "income.gifts", "income.other"]

  /// Mirrors core `categoryTypes`: the column's JSON list, "[]"/"none" for none on purpose, a bare
  /// key as a list of one; nothing stated, the preset's. Unknown keys are dropped.
  static func types(_ raw: String?, preset: String?) -> [String] {
    if let raw, !raw.isEmpty {
      if raw == "none" { return [] }
      if raw.hasPrefix("["), let data = raw.data(using: .utf8), let list = (try? JSONSerialization.jsonObject(with: data)) as? [Any] {
        var out: [String] = []
        for case let k as String in list where known.contains(k) && !out.contains(k) { out.append(k) }
        return out
      }
      if known.contains(raw) { return [raw] }
    }
    if let preset, known.contains(preset) { return [preset] }
    return []
  }
  /// Mirrors core `isPlaceless`: every one of its types is placeless.
  static func isPlaceless(_ types: [String]) -> Bool { !types.isEmpty && types.allSatisfy { placeless.contains($0) } }

  /// Mirrors core `normalizeName`: lower case, ł → l, accents off, anything but a-z, 0-9 and
  /// Cyrillic a space, spaces collapsed. The two must agree or a shop matches on one side only.
  static func normalize(_ s: String) -> String {
    let lowered = s.lowercased().replacingOccurrences(of: "ł", with: "l")
    var out = ""
    var space = false
    for u in lowered.decomposedStringWithCompatibilityMapping.unicodeScalars {
      if (0x300...0x36F).contains(u.value) { continue }
      let keep = (u.value >= 0x61 && u.value <= 0x7A) || (u.value >= 0x30 && u.value <= 0x39) || (0x400...0x4FF).contains(u.value)
      if keep { if space && !out.isEmpty { out.append(" ") }; space = false; out.unicodeScalars.append(u) } else { space = true }
    }
    return out
  }

  /// The type a shop's name says it is, or nil: whole words, longest term first, each name in turn.
  static func type(_ names: String?...) -> String? {
    for raw in names {
      guard let raw else { continue }
      let n = " \(normalize(raw)) "
      if n.count < 4 { continue }
      for t in terms where n.contains(" \(t.term) ") { return t.type }
    }
    return nil
  }
}
